import requests

def extract_tables(payload, config=None):
    config = config or {}
    endpoint = config.get("endpoint", os.environ.get("AZURE_AI_DOCUMENT_ENDPOINT"))
    key = config.get("key", os.environ.get("AZURE_AI_DOCUMENT_KEY"))
    headers = {"Ocp-Apim-Subscription-Key": key, "Content-Type": "application/octet-stream"}
    url = f"{endpoint.rstrip('/')}formrecognizer/documentmodels/prebuilt-layout:analyze?api-version=2023-07-31"
    response = requests.post(url, headers=headers, data=payload)
    result = requests.get(response.headers["Operation-Location"], headers=headers).json()
    return result
